@import 'tailwindcss';

@font-face {
  font-family: 'Plus Jakarta Sans Variable';
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url('/fonts/jakarta-var.woff2') format('woff2');
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304,
    U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF;
}

@theme {
  --font-sans: 'Plus Jakarta Sans Variable', 'Plus Jakarta Sans', ui-sans-serif, system-ui,
    sans-serif;

  --letter-spacing-heading: -0.015em;
  --ease-spring: linear(
    0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 23.4%,
    0.849 28%, 0.937 32.6%, 0.995 37.6%, 1.019 42.2%, 1.026 47.1%, 1.021 54%,
    1.001 68.8%, 0.996 82.5%, 1
  );

  /* Hark Pro Squircle Geometry Radii */
  --r-squircle-sm: 18px;
  --r-squircle-md: 20px;
  --r-squircle-lg: 24px;
  --r-squircle-xl: 26px;

  --radius-squircle-sm: 18px;
  --radius-squircle-md: 20px;
  --radius-squircle-lg: 24px;
  --radius-squircle-xl: 26px;
  --radius-full: 9999px;

  --animate-rise: rise 0.6s linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 23.4%, 0.849 28%, 0.937 32.6%, 0.995 37.6%, 1.019 42.2%, 1.026 47.1%, 1.021 54%, 1.001 68.8%, 0.996 82.5%, 1) both;
  --animate-drift: drift 18s ease-in-out infinite;
  --animate-wave: wave 0.9s ease-in-out infinite;

  @keyframes rise {
    0% {
      opacity: 0;
      transform: translateY(12px);
    }
    100% {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @keyframes drift {
    0%,
    100% {
      transform: translate3d(0, 0, 0) scale(1);
    }
    50% {
      transform: translate3d(2%, -3%, 0) scale(1.06);
    }
  }

  @keyframes wave {
    0%,
    100% {
      transform: scaleY(0.25);
    }
    50% {
      transform: scaleY(1);
    }
  }
}

/* ---------------------------------------------------------------------------------------------
   Palette. Set on <html data-theme="light|dark"> by the inline bootstrap in index.html, before
   first paint, so there is never a flash of the wrong theme.
   --------------------------------------------------------------------------------------------- */

:root,
[data-theme='dark'] {
  color-scheme: dark;

  /* Spring easing & squircle geometry */
  --ease-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 23.4%, 0.849 28%, 0.937 32.6%, 0.995 37.6%, 1.019 42.2%, 1.026 47.1%, 1.021 54%, 1.001 68.8%, 0.996 82.5%, 1);
  --r-squircle-sm: 18px;
  --r-squircle-md: 20px;
  --r-squircle-lg: 24px;
  --r-squircle-xl: 26px;

  /* Typography */
  --font-sans: 'Plus Jakarta Sans Variable', 'Plus Jakarta Sans', ui-sans-serif, system-ui, sans-serif;
  --letter-spacing-heading: -0.015em;

  /* Obsidian Horizon Palette */
  --bg-from: #0a0a0c;
  --bg-to: #121216;
  --surface-solid: #0d1320;
  --card: rgba(22, 22, 26, 0.7);
  --card-hover: rgba(30, 30, 36, 0.85);
  --card-strong: rgba(38, 38, 46, 0.92);
  --card-highlight: rgba(255, 255, 255, 0.08);
  --border: rgba(255, 255, 255, 0.08);
  --border-strong: rgba(255, 255, 255, 0.18);

  /* Specular Rim Catchlight */
  --shadow-rim: inset 0 1px 0 0 rgba(255, 255, 255, 0.08);
  --specular-rim: inset 0 1px 0 0 rgba(255, 255, 255, 0.08);
  --specular-rim-strong: inset 0 1px 0 0 rgba(255, 255, 255, 0.15);

  --accent: #38bdf8;
  --accent-ink: #070a10;
  --accent-soft: rgba(56, 189, 248, 0.12);
  --accent-glow: rgba(56, 189, 248, 0.28);
  --text: #f8fafc;
  --text-muted: #94a3b8;
  --glass: rgba(13, 19, 32, 0.72);
  --shadow: 0 20px 50px rgba(0, 0, 0, 0.55), 0 4px 14px rgba(0, 0, 0, 0.35);

  /* Proactivity Tags */
  --tag-urgent-bg: rgba(239, 68, 68, 0.14);
  --tag-urgent-text: #fca5a5;
  --tag-urgent-border: rgba(239, 68, 68, 0.28);

  --tag-decision-bg: rgba(245, 158, 11, 0.14);
  --tag-decision-text: #fcd34d;
  --tag-decision-border: rgba(245, 158, 11, 0.28);

  --tag-autonomous-bg: rgba(56, 189, 248, 0.14);
  --tag-autonomous-text: #7dd3fc;
  --tag-autonomous-border: rgba(56, 189, 248, 0.28);

  --tag-proactive-bg: rgba(56, 189, 248, 0.12);
  --tag-proactive-text: #7dd3fc;
  --tag-proactive-border: rgba(56, 189, 248, 0.24);

  /* Urgency Rails (3px border indicator) */
  --urgency-critical: #f87171;
  --urgency-high: #fb923c;
  --urgency-medium: #94a3b8;
  --urgency-low: #64748b;

  /* Verb Pills */
  --btn-primary-bg: #f8fafc;
  --btn-primary-ink: #070a10;
  --verb-pill-bg: #f8fafc;
  --verb-pill-text: #070a10;
  --verb-pill-hover-bg: #ffffff;
  --verb-pill-secondary-bg: rgba(255, 255, 255, 0.08);
  --verb-pill-secondary-text: #f8fafc;
  --verb-pill-secondary-border: rgba(255, 255, 255, 0.14);
  --verb-pill-secondary-hover-bg: rgba(255, 255, 255, 0.12);

  /* Approval Surfaces */
  --approval-bg: rgba(245, 158, 11, 0.08);
  --approval-border: rgba(245, 158, 11, 0.25);
  --approval-text: #fde68a;
  --approval-text-muted: #fcd34d;
  --surface-approval: rgba(245, 158, 11, 0.08);
  --border-approval: rgba(245, 158, 11, 0.25);

  /* Background atmosphere & clouds */
  --cloud-1: rgba(255, 255, 255, 0.045);
  --cloud-2: rgba(56, 189, 248, 0.035);
  --cloud-3: rgba(232, 132, 73, 0.12);
  --horizon: rgba(10, 10, 12, 0.88);
  --grain-opacity: 0.07;
  --sky-accent: #38bdf8;
  --sun-accent: #fb923c;
  --focus-ring: #38bdf8;
}

[data-theme='light'] {
  color-scheme: light;

  /* Spring easing & squircle geometry */
  --ease-spring: linear(0, 0.006, 0.025 2.8%, 0.101 6.1%, 0.539 18.9%, 0.721 23.4%, 0.849 28%, 0.937 32.6%, 0.995 37.6%, 1.019 42.2%, 1.026 47.1%, 1.021 54%, 1.001 68.8%, 0.996 82.5%, 1);
  --r-squircle-sm: 18px;
  --r-squircle-md: 20px;
  --r-squircle-lg: 24px;
  --r-squircle-xl: 26px;

  /* Typography */
  --font-sans: 'Plus Jakarta Sans Variable', 'Plus Jakarta Sans', ui-sans-serif, system-ui, sans-serif;
  --letter-spacing-heading: -0.015em;

  /* Tactile Alabaster Palette */
  --bg-from: #f8f7f5;
  --bg-to: #f0eee9;
  --surface-solid: #ffffff;
  --card: rgba(255, 255, 255, 0.85);
  --card-hover: rgba(255, 255, 255, 0.95);
  --card-strong: #ede8de;
  --card-highlight: rgba(255, 255, 255, 0.95);
  --border: rgba(0, 0, 0, 0.08);
  --border-strong: rgba(0, 0, 0, 0.18);

  /* Specular Rim Catchlight */
  --shadow-rim: inset 0 1px 0 0 rgba(255, 255, 255, 0.9);
  --specular-rim: inset 0 1px 0 0 rgba(255, 255, 255, 0.9);
  --specular-rim-strong: inset 0 1px 0 0 #ffffff;

  --accent: #0284c7;
  --accent-ink: #ffffff;
  --accent-soft: rgba(2, 132, 199, 0.10);
  --accent-glow: rgba(2, 132, 199, 0.22);
  --text: #0f172a;
  --text-muted: #64748b;
  --glass: rgba(248, 247, 245, 0.75);
  --shadow: 0 20px 50px rgba(15, 23, 42, 0.06), 0 4px 14px rgba(15, 23, 42, 0.03);

  /* Proactivity Tags */
  --tag-urgent-bg: rgba(220, 38, 38, 0.08);
  --tag-urgent-text: #b91c1c;
  --tag-urgent-border: rgba(220, 38, 38, 0.20);

  --tag-decision-bg: rgba(217, 119, 6, 0.08);
  --tag-decision-text: #b45309;
  --tag-decision-border: rgba(217, 119, 6, 0.20);

  --tag-autonomous-bg: rgba(2, 132, 199, 0.08);
  --tag-autonomous-text: #0369a1;
  --tag-autonomous-border: rgba(2, 132, 199, 0.20);

  --tag-proactive-bg: rgba(2, 132, 199, 0.08);
  --tag-proactive-text: #0369a1;
  --tag-proactive-border: rgba(2, 132, 199, 0.20);

  /* Urgency Rails (3px border indicator) */
  --urgency-critical: #dc2626;
  --urgency-high: #ea580c;
  --urgency-medium: #64748b;
  --urgency-low: #94a3b8;

  /* Verb Pills */
  --btn-primary-bg: #0f172a;
  --btn-primary-ink: #ffffff;
  --verb-pill-bg: #0f172a;
  --verb-pill-text: #ffffff;
  --verb-pill-hover-bg: #1e293b;
  --verb-pill-secondary-bg: rgba(15, 23, 42, 0.06);
  --verb-pill-secondary-text: #0f172a;
  --verb-pill-secondary-border: rgba(15, 23, 42, 0.12);
  --verb-pill-secondary-hover-bg: rgba(15, 23, 42, 0.10);

  /* Approval Surfaces */
  --approval-bg: rgba(217, 119, 6, 0.08);
  --approval-border: rgba(217, 119, 6, 0.22);
  --approval-text: #b45309;
  --approval-text-muted: #92400e;
  --surface-approval: rgba(217, 119, 6, 0.08);
  --border-approval: rgba(217, 119, 6, 0.22);

  /* Background atmosphere & clouds */
  --cloud-1: rgba(244, 166, 108, 0.18);
  --cloud-2: rgba(121, 187, 232, 0.15);
  --cloud-3: rgba(112, 178, 226, 0.10);
  --horizon: rgba(240, 238, 233, 0.45);
  --grain-opacity: 0.025;
  --sky-accent: #0284c7;
  --sun-accent: #ea580c;
  --focus-ring: #0284c7;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  background: linear-gradient(155deg, var(--bg-from), var(--bg-to));
  background-attachment: fixed;
  color: var(--text);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  transition:
    background 0.5s var(--ease-spring),
    color 0.4s;
}

h1,
h2,
h3,
h4,
h5,
h6,
.tracking-heading {
  letter-spacing: var(--letter-spacing-heading);
}

::selection {
  background: color-mix(in srgb, var(--sky-accent) 24%, transparent);
}

:where(button, a):focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 3px;
}

.glass {
  background: var(--glass);
  -webkit-backdrop-filter: blur(40px) saturate(140%);
  backdrop-filter: blur(40px) saturate(140%);
  border: 1px solid color-mix(in srgb, var(--text) 10%, transparent);
  box-shadow: var(--shadow);
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  box-shadow: var(--shadow), var(--shadow-rim);
  -webkit-backdrop-filter: blur(30px) saturate(140%);
  backdrop-filter: blur(30px) saturate(140%);
  transition: background 0.4s var(--ease-spring);
}
.card:hover {
  background: var(--card-hover);
}

/* Softer surface for chat bubbles and small tiles */
.bubble {
  background: var(--card);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-rim);
  -webkit-backdrop-filter: blur(24px) saturate(140%);
  backdrop-filter: blur(24px) saturate(140%);
}

/* Button system: solid primary, tinted soft, outlined ghost, quiet text */
.btn {
  display: inline-flex;
  height: 40px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border-radius: 10px;
  padding: 0 20px;
  font-size: 14px;
  font-weight: 600;
  line-height: 1;
  white-space: nowrap;
  border: 1px solid transparent;
  transition:
    transform 0.45s var(--ease-spring),
    background 0.3s,
    color 0.3s,
    opacity 0.3s;
}
.btn:hover {
  transform: scale(1.03);
}
.btn:active {
  transform: scale(0.96);
}
.btn:focus-visible {
  border-color: var(--border-strong);
}
.btn:disabled {
  opacity: 0.6;
  pointer-events: none;
}
.btn-primary {
  background: var(--btn-primary-bg);
  color: var(--btn-primary-ink);
}
.btn-soft {
  background: color-mix(in srgb, var(--text) 9%, transparent);
  color: var(--text);
}
.btn-soft:hover {
  background: color-mix(in srgb, var(--text) 13%, transparent);
}
.btn-ghost {
  border-color: var(--border-strong);
  color: var(--text);
}
.btn-ghost:hover {
  background: color-mix(in srgb, var(--text) 6%, transparent);
}
.btn-quiet {
  padding: 0 14px;
  color: var(--text-muted);
}
.btn-quiet:hover {
  color: var(--text);
  background: color-mix(in srgb, var(--text) 6%, transparent);
}

/* Squircle Utilities */
.rounded-squircle-sm { border-radius: var(--r-squircle-sm); }
.rounded-squircle-md { border-radius: var(--r-squircle-md); }
.rounded-squircle-lg { border-radius: var(--r-squircle-lg); }
.rounded-squircle-xl { border-radius: var(--r-squircle-xl); }

/* Verb Pills */
.verb-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 16px;
  border-radius: var(--r-squircle-sm);
  background: var(--verb-pill-bg);
  color: var(--verb-pill-text);
  font-size: 13px;
  font-weight: 600;
  box-shadow: var(--shadow-rim);
  transition: transform 0.3s var(--ease-spring), opacity 0.2s, background 0.2s;
}
.verb-pill:hover {
  background: var(--verb-pill-hover-bg);
  transform: scale(1.02);
}
.verb-pill:active {
  transform: scale(0.97);
}

.verb-pill-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  height: 36px;
  padding: 0 16px;
  border-radius: var(--r-squircle-sm);
  background: var(--verb-pill-secondary-bg);
  color: var(--verb-pill-secondary-text);
  border: 1px solid var(--verb-pill-secondary-border);
  font-size: 13px;
  font-weight: 500;
  transition: transform 0.3s var(--ease-spring), background 0.2s;
}
.verb-pill-secondary:hover {
  background: var(--verb-pill-secondary-hover-bg);
  transform: scale(1.02);
}
.verb-pill-secondary:active {
  transform: scale(0.97);
}

/* Approval Surface */
.approval-surface {
  background: var(--approval-bg);
  border: 1px solid var(--approval-border);
  border-radius: var(--r-squircle-md);
  box-shadow: var(--shadow-rim);
}

.scroll-soft {
  scrollbar-width: thin;
  scrollbar-color: color-mix(in srgb, var(--text) 18%, transparent) transparent;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

@utility tabular {
  font-variant-numeric: tabular-nums;
}

/* ══ KaTeX & Markdown Overflow Protection ════════════════════
   Ensure display math equations scroll horizontally inside their
   own container and never blow out the chat column width. */
.katex-display {
  overflow-x: auto;
  overflow-y: hidden;
  max-width: 100%;
  margin: 0.85em 0 !important;
  padding: 0.5rem 0.75rem;
  border-radius: 10px;
  background: color-mix(in srgb, var(--text) 3.5%, transparent);
  border: 1px solid var(--border);
  scrollbar-width: thin;
}

.katex {
  font-size: 1.04em !important;
  line-height: 1.3;
}

